#!/usr/bin/env python3
"""Regenerate deterministic ground truth for CSX-096 Q2."""

from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path
from typing import Any


TASK_ID = "CSX-096_Q2"
EVENT_ID = "CSX-096"
TARGET_FAMILY = "pakistan_2022_monsoon_indus_persistence_gate"


def project_root() -> Path:
    return Path(__file__).resolve().parents[3]


ROOT = project_root()
PKG = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT = ROOT / "benchmark_build" / "individual_event_tasks" / TASK_ID / "computed_gt.json"


def load_json(relative_path: str) -> Any:
    with (PKG / relative_path).open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def inclusive_days(start: str, end: str) -> int:
    return (datetime.strptime(end, "%Y-%m-%d") - datetime.strptime(start, "%Y-%m-%d")).days + 1


def rolling_sum(values: list[float], window: int) -> float:
    return max(sum(values[index : index + window]) for index in range(len(values) - window + 1))


def pakistan_gdacs_flood_days(gdacs: dict[str, Any]) -> int:
    for feature in gdacs.get("features", []):
        props = feature.get("properties", {})
        if props.get("eventtype") == "FL" and props.get("iso3") == "PAK":
            return inclusive_days(str(props["fromdate"])[:10], str(props["todate"])[:10])
    raise ValueError("Pakistan GDACS flood record missing")


def build_result() -> dict[str, Any]:
    event = load_json("metadata/event.json")
    anchor = load_json("data/event_reports/event_reports_003_Locked_event_anchor_2022_Pakistan_monsoon_floods.json")
    gdacs = load_json("data/event_catalogs/event_catalogs_001_GDACS_event_list_GeoJSON_API.json")
    power = load_json("data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json")
    era5 = load_json("data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json")
    gpm = load_json("data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = load_json("data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json")

    locked = anchor["locked_event_anchor"]
    event_start = locked["event_start_date"]
    event_end = locked["event_end_date"]
    event_days = inclusive_days(event_start, event_end)

    daily_precip = [
        float(value)
        for _, value in sorted(power["properties"]["parameter"]["PRECTOTCORR"].items())
    ]
    point_total_mm = sum(daily_precip)
    event_mean_daily_mm = point_total_mm / event_days
    daily_peak_mm = max(daily_precip)
    heavy_rain_days = sum(1 for value in daily_precip if value >= 10.0)
    max_7day_mm = rolling_sum(daily_precip, 7)

    grid_means = {
        "era5_land": float(era5["stats"]["precipitation_sum_mm_mean"]),
        "gpm_imerg": float(gpm["stats"]["gpm_event_precip_mm_mean"]),
        "chirps": float(chirps["stats"]["chirps_event_precip_mm_mean"]),
    }
    gridded_window = {
        "start_date": gpm["start"],
        "end_date": gpm["end"],
        "inclusive_days": inclusive_days(gpm["start"], gpm["end"]),
        "role": "declared_shared_gridded_comparison_window_not_full_event_window",
    }
    grid_mean_consensus_mm = sum(grid_means.values()) / len(grid_means)
    grid_mean_spread_fraction = (
        max(grid_means.values()) - min(grid_means.values())
    ) / grid_mean_consensus_mm

    gdacs_red_flood_days = pakistan_gdacs_flood_days(gdacs)
    metrics = {
        "peak_to_mean_intensity": round(daily_peak_mm / event_mean_daily_mm, 3),
        "heavy_rain_persistence": round(heavy_rain_days / event_days, 4),
        "red_window_fraction": round(gdacs_red_flood_days / event_days, 4),
        "grid_mean_spread_fraction": round(grid_mean_spread_fraction, 4),
        "peak_window_share": round(max_7day_mm / point_total_mm, 4),
    }
    gates = {
        "intensity_gate": metrics["peak_to_mean_intensity"] >= 8.0,
        "persistence_gate": metrics["heavy_rain_persistence"] >= 0.25
        and metrics["red_window_fraction"] >= 0.70,
        "regional_consensus_gate": metrics["grid_mean_spread_fraction"] <= 0.10,
        "pulse_guardrail": metrics["peak_window_share"] < 0.40,
    }
    final_label = (
        "sustained_indus_storage_signal"
        if all(gates.values())
        else "short_pulse_or_inconclusive_signal"
    )

    primary_gt = {
        "target_family": TARGET_FAMILY,
        "metrics": metrics,
        "gates": gates,
        "final_label": final_label,
        "computed_consequence": "persistent_loading_outweighs_short_peak"
        if final_label == "sustained_indus_storage_signal"
        else "persistence_gate_not_met",
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "target_family": TARGET_FAMILY,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Requested JSON form",
                    "points": 3,
                    "description": "Returns compact JSON with target_family, metrics, gates, final_label, and computed_consequence.",
                    "partial_credit": "Award 1-2 points if the response is mostly complete but omits one required field or gives a field in an unusable shape.",
                },
                {
                    "name": "Event window and rainfall anchors",
                    "points": 4,
                    "description": "Computes the 109-day window, 1493.3 mm point total, 150.3 mm daily peak, and 31 days at or above 10 mm/day.",
                    "partial_credit": "Award 1-3 points for a correct window with one or two incorrect rainfall anchors, or correct rainfall anchors with a minor window error.",
                },
                {
                    "name": "Intensity ratio",
                    "points": 3,
                    "description": "Computes peak_to_mean_intensity as the daily peak divided by the event-window daily mean, yielding 10.972 within tolerance.",
                    "partial_credit": "Award 1-2 points for the right formula with rounding or denominator errors that still preserve the gate outcome.",
                },
                {
                    "name": "Persistence fractions",
                    "points": 4,
                    "description": "Computes heavy_rain_persistence of 0.2844 and red_window_fraction of 0.7248 within tolerance.",
                    "partial_credit": "Award 1-3 points if only one fraction is correct or both use the correct counts but the wrong denominator or rounding.",
                },
                {
                    "name": "Consensus and pulse guardrail",
                    "points": 3,
                    "description": "Computes grid_mean_spread_fraction of 0.0661 over the declared 2022-06-14 to 2022-07-29 gridded comparison window, computes peak_window_share of 0.3244 over the point series, and applies the stated thresholds.",
                    "partial_credit": "Award 1-2 points if one metric is correct or the formulas are correct but the values are slightly outside tolerance.",
                },
                {
                    "name": "Gate-derived final label",
                    "points": 2,
                    "description": "Marks all four gates true and returns sustained_indus_storage_signal.",
                    "partial_credit": "Award 1 point if the gate booleans are mostly correct but the final label or one threshold comparison is wrong.",
                },
                {
                    "name": "Concise consequence",
                    "points": 1,
                    "description": "Keeps the consequence as a short computed result and avoids loss accounting from local surface or receptor values.",
                    "partial_credit": "Award 0.5 points if the consequence is directionally correct but adds minor extra detail.",
                },
            ],
        },
        "event": {
            "package_id": EVENT_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": f"{event_start} to {event_end}",
        },
        "decision_rule": {
            "summary": "All four deterministic gates must pass for the sustained Indus storage signal.",
            "formulas": {
                "peak_to_mean_intensity": "daily_peak_mm / (point_total_mm / event_days)",
                "heavy_rain_persistence": "days_ge_10mm / event_days",
                "red_window_fraction": "gdacs_red_flood_days / event_days",
                "grid_mean_spread_fraction": "(max(gridded_window_means) - min(gridded_window_means)) / mean(gridded_window_means)",
                "peak_window_share": "max_7day_precip_mm / point_total_mm",
            },
            "thresholds": {
                "intensity_gate": "peak_to_mean_intensity >= 8.0",
                "persistence_gate": "heavy_rain_persistence >= 0.25 and red_window_fraction >= 0.70",
                "regional_consensus_gate": "grid_mean_spread_fraction <= 0.10",
                "pulse_guardrail": "peak_window_share < 0.40",
            },
        },
        "key_values": {
            "event_days": event_days,
            "point_total_mm": round(point_total_mm, 1),
            "event_mean_daily_mm": round(event_mean_daily_mm, 3),
            "daily_peak_mm": round(daily_peak_mm, 1),
            "heavy_rain_days_ge_10mm": heavy_rain_days,
            "gdacs_red_flood_days": gdacs_red_flood_days,
            "gridded_comparison_window": gridded_window,
            "gridded_window_means_mm": {key: round(value, 1) for key, value in grid_means.items()},
            "gridded_window_mean_consensus_mm": round(grid_mean_consensus_mm, 1),
            "max_7day_precip_mm": round(max_7day_mm, 2),
        },
        "numeric_tolerances": {
            "peak_to_mean_intensity": {"target": 10.972, "absolute_tolerance": 0.001},
            "heavy_rain_persistence": {"target": 0.2844, "absolute_tolerance": 0.0001},
            "red_window_fraction": {"target": 0.7248, "absolute_tolerance": 0.0001},
            "grid_mean_spread_fraction": {"target": 0.0661, "absolute_tolerance": 0.0001},
            "peak_window_share": {"target": 0.3244, "absolute_tolerance": 0.0001},
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "data/event_reports/event_reports_003_Locked_event_anchor_2022_Pakistan_monsoon_floods.json",
                "data/event_catalogs/event_catalogs_001_GDACS_event_list_GeoJSON_API.json",
                "data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json",
                "data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json",
                "data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json",
                "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
            ],
            "notes": "Deterministic local-file calculation with fixed formulas and numeric tolerances. Point rainfall and GDACS duration use the full locked flood window; ERA5/GPM/CHIRPS precipitation means are scored only as cross-product agreement over their declared 2022-06-14 to 2022-07-29 gridded comparison window.",
        },
    }


def main() -> None:
    OUT.write_text(json.dumps(build_result(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
